#include <Game/SoundEffects.hpp>
#include <gtest/gtest.h>

using gyrus::game::SoundEffects;

namespace {
void hashChannels(std::uint64_t& hash, const SoundEffects& effects) {
    for (const auto& channel : effects.channels()) {
        for (const auto byte : {channel.frequency, channel.control,
                               static_cast<std::uint8_t>(channel.active)}) {
            hash = (hash ^ byte) * 1099511628211ULL;
        }
    }
}
} // namespace

// Independently generated by running the original $B995/$B9DB routines in
// py65 1.2.0: tools/reverse/audio_oracle.py --fixtures. Hash order is channel
// 1..4, each AUDF/AUDC/active, after each frame 0..1023. It covers counter wrap,
// effect completion, retained registers on skipped frames, and transitions.
TEST(SoundEffectsTest, EveryEffectMatchesOriginal1024FrameTrace) {
    constexpr std::array<std::uint64_t, 10> expected{
        0xf3ba4509b5f734e2ULL, 0x710acd3aec85c2d2ULL, 0x3ce3b4d5d999b786ULL,
        0x8afc6e09a11726ceULL, 0x0014bc086fb39ad2ULL, 0xc952d9d1c5d1af3eULL,
        0x5e82fdd6d1bc7cd5ULL, 0xcf1c8c3131fc2285ULL, 0xb22e17020ad0115dULL,
        0xf8523a3aa6a74466ULL};
    for (std::uint8_t id = 0; id < expected.size(); ++id) {
        SCOPED_TRACE(static_cast<unsigned>(id));
        SoundEffects effects;
        ASSERT_TRUE(effects.start(id));
        std::uint64_t hash = 14695981039346656037ULL;
        for (unsigned frame = 0; frame < 1024; ++frame) {
            effects.tick(static_cast<std::uint8_t>(frame));
            hashChannels(hash, effects);
        }
        EXPECT_EQ(hash, expected[id]);
    }
}

TEST(SoundEffectsTest, ConcurrentAndReplacementEffectsMatchOriginal1024FrameTrace) {
    constexpr std::array<unsigned, 12> times{0,3,10,20,40,45,100,110,200,201,600,800};
    constexpr std::array<std::uint8_t, 12> ids{0,7,9,4,2,8,1,5,6,3,2,8};
    SoundEffects effects;
    std::uint64_t hash = 14695981039346656037ULL;
    for (unsigned frame = 0; frame < 1024; ++frame) {
        for (unsigned i = 0; i < times.size(); ++i) {
            if (frame == times[i]) {
                ASSERT_TRUE(effects.start(ids[i]));
            }
        }
        effects.tick(static_cast<std::uint8_t>(frame));
        hashChannels(hash, effects);
    }
    EXPECT_EQ(hash, 0x65e6b66712f4dac9ULL);
}

TEST(SoundEffectsTest, StartingAnEffectPreservesRegistersUntilNextUpdate) {
    SoundEffects effects;
    ASSERT_TRUE(effects.start(0));
    effects.tick(1);
    const auto previous = effects.channels()[3];
    EXPECT_EQ(previous.control, 0x0b);
    EXPECT_EQ(previous.frequency, 3);
    ASSERT_TRUE(effects.start(7));
    EXPECT_EQ(effects.channels()[3], previous);
}

TEST(SoundEffectsTest, InvalidIdDoesNotReplaceAnActiveEffect) {
    SoundEffects actual;
    SoundEffects expected;
    ASSERT_TRUE(actual.start(6));
    ASSERT_TRUE(expected.start(6));
    EXPECT_FALSE(actual.start(10));
    EXPECT_FALSE(actual.start(255));
    for (unsigned frame = 0; frame < 512; ++frame) {
        actual.tick(static_cast<std::uint8_t>(frame));
        expected.tick(static_cast<std::uint8_t>(frame));
        EXPECT_EQ(actual.channels(), expected.channels());
    }
}

TEST(SoundEffectsTest, UnstartedChannelsRemainSilent) {
    SoundEffects effects;
    for (unsigned frame = 0; frame < 512; ++frame) {
        effects.tick(static_cast<std::uint8_t>(frame));
        EXPECT_EQ(effects.channels(), (std::array<SoundEffects::Channel, 4>{}));
    }
}
